package Day3;

public class DoWhileLoopDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
         
		int i=100;
		
		do {
			System.out.println("Dev Kumar Chaubey "+i);
			i=i+1;
		}
		while(i<=5);  //condition is checked at exit last time
	}

}

/* output 
Dev Kumar Chaubey 100
*/